//! The extension's real acks (generated by `apps/extension/scripts/bridge-fixtures.ts` from
//! the `Adapter`) read as the engine expects. An ack with skipped or failed tabs is
//! `ok: false` *with* a result: the engine settles from the result, not from `ok`.

use decay_bridge::protocol::{Ack, CloseResult, ErrorCode, ProbeAck, RestoreResult, SkipReason};
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    probe: Ack,
    close: Ack,
    close_changed: Ack,
    restore: Ack,
    unknown_command: Ack,
}

fn result<T: serde::de::DeserializeOwned>(ack: &Ack) -> T {
    serde_json::from_value(ack.result.clone().expect("a result")).expect("the result parses")
}

#[test]
fn adapter_acks_parse() {
    let f: Fixture = serde_json::from_str(include_str!("fixtures/adapter_acks.json")).unwrap();

    let probe: ProbeAck = result(&f.probe);
    assert!(f.probe.ok);
    let verdicts: Vec<(i64, bool, bool)> =
        probe.results.iter().map(|r| (r.tab_id, r.dirty_form, r.unknown)).collect();
    assert_eq!(verdicts, vec![(1, false, false), (3, true, false), (4, false, true)]);
    assert_eq!(probe.missing, vec![99]);

    assert!(!f.close.ok);
    assert_eq!(f.close.error.as_ref().map(|e| e.code), Some(ErrorCode::Unsafe));
    let close: CloseResult = result(&f.close);
    assert_eq!(close.closed, vec![1, 4, 5]);
    assert_eq!(close.unchecked, vec![4]);
    let skipped: Vec<(i64, SkipReason)> =
        close.skipped.iter().map(|s| (s.tab_id, s.reason)).collect();
    assert_eq!(
        skipped,
        vec![
            (2, SkipReason::Active),
            (3, SkipReason::FormInput),
            (6, SkipReason::Pinned),
            (7, SkipReason::InUse),
        ]
    );
    let changed: CloseResult = result(&f.close_changed);
    assert_eq!(changed.skipped[0].reason, SkipReason::Changed);

    assert!(!f.restore.ok);
    let restore: RestoreResult = result(&f.restore);
    assert_eq!(restore.restored.len(), 1);
    assert_eq!((restore.restored[0].item_id.as_str(), restore.restored[0].tab_id), ("item-a", 100));
    assert_eq!(restore.failed, vec!["item-b".to_owned()]);

    assert_eq!(f.unknown_command.error.map(|e| e.code), Some(ErrorCode::BadMessage));
    assert!(f.unknown_command.result.is_none());
}
